{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Methoxsalen, the closest structural analogue with a methoxy-substituted coumarin core, showed relatively low systemic bioavailability in humans, directly supporting low oral bioavailability for the query's coumarin scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Apocynin, a small methoxyphenol, had <10% oral bioavailability in humans, supporting low F for the query's methoxy-phenolic absorption and first-pass metabolism liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ferulic acid, another methoxyhydroxyphenyl compound, showed only 3-10% bioavailability in humans, reinforcing that this phenolic/methoxy motif is associated with low systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Curcumin had barely 1% absolute oral bioavailability in humans, illustrating very low F for polyphenolic compounds, though transferability to the smaller query is limited by size and polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Isoeugenol, a small methoxyphenol, showed 35.8-39.0% oral bioavailability in humans, the only above-threshold evidence, but its simple phenylpropene structure is less transferable to the coumarin-containing query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable human evidence, especially the closest analogue methoxsalen (a methoxycoumarin with low systemic availability) and small methoxyphenols with <10% F, supports low oral bioavailability for the query. The single high value for isoeugenol is outweighed by lower structural transferability and coumarin-specific metabolic/conjugation liabilities.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for scopoletin itself.",
    "The methoxsalen record is qualitative ('relatively low') rather than a numeric F value.",
    "The only above-threshold evidence (isoeugenol) has limited structural overlap with the coumarin query.",
    "Potential species differences between human and rodent bioavailability data are not fully resolved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

